const http = require('http');
const sharp = require('sharp');
const { Pool } = require('generic-pool');
const crypto = require('crypto');

const STATE = {
  connections: new Map(),
  processing: new Map(),
  shuttingDown: false,
  drainPromise: null,
  activeRequests: 0
};

const poolFactory = {
  create: async () => {
    const id = crypto.randomBytes(8).toString('hex');
    const conn = { id, busy: false, buffer: null, created: Date.now() };
    STATE.connections.set(id, conn);
    return conn;
  },
  destroy: async (conn) => {
    STATE.connections.delete(conn.id);
    conn.buffer = null;
  },
  validate: (conn) => {
    return !STATE.shuttingDown && (Date.now() - conn.created) < 30000;
  }
};

const pool = Pool(poolFactory, { min: 2, max: 10, testOnBorrow: true });

async function processImage(inputBuffer, options) {
  const conn = await pool.acquire();
  conn.busy = true;
  conn.buffer = inputBuffer;
  STATE.processing.set(conn.id, { startTime: Date.now(), options });

  try {
    let pipeline = sharp(conn.buffer);

    if (options.width || options.height) {
      pipeline = pipeline.resize(options.width, options.height, {
        fit: options.fit || 'cover',
        withoutEnlargement: true
      });
    }

    if (options.format) {
      pipeline = pipeline.toFormat(options.format, { quality: options.quality || 80 });
    }

    const result = await pipeline.toBuffer();
    return result;
  } finally {
    conn.busy = false;
    conn.buffer = null;
    STATE.processing.delete(conn.id);
    pool.release(conn);
  }
}

function initiateGracefulShutdown(signal) {
  if (STATE.shuttingDown) return;
  STATE.shuttingDown = true;
  console.log(`Received ${signal}, starting graceful shutdown...`);

  STATE.drainPromise = new Promise((resolve) => {
    const checkDrained = () => {
      if (STATE.activeRequests <= 0) {
        resolve();
      } else {
        setTimeout(checkDrained, 100);
      }
    };
    checkDrained();
  });

  STATE.drainPromise.then(async () => {
    for (const [id, conn] of STATE.connections) {
      if (conn.buffer) {
        conn.buffer = null;
      }
    }
    await pool.drain();
    await pool.clear();
    server.close(() => process.exit(0));
  });

  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
}

process.on('SIGTERM', () => initiateGracefulShutdown('SIGTERM'));
process.on('SIGINT', () => initiateGracefulShutdown('SIGINT'));

const server = http.createServer(async (req, res) => {
  if (STATE.shuttingDown) {
    res.writeHead(503);
    res.end('Service shutting down');
    return;
  }

  STATE.activeRequests++;

  try {
    if (req.method === 'POST' && req.url === '/process') {
      const chunks = [];
      for await (const chunk of req) {
        chunks.push(chunk);
      }
      const body = Buffer.concat(chunks);

      const widthHeader = req.headers['x-resize-width'];
      const heightHeader = req.headers['x-resize-height'];
      const formatHeader = req.headers['x-output-format'];

      const options = {
        width: widthHeader ? parseInt(widthHeader, 10) : undefined,
        height: heightHeader ? parseInt(heightHeader, 10) : undefined,
        format: formatHeader || undefined,
        quality: 85
      };

      const result = await processImage(body, options);
      res.writeHead(200, { 'Content-Type': `image/${options.format || 'png'}` });
      res.end(result);
    } else if (req.method === 'GET' && req.url === '/health') {
      const status = {
        connections: STATE.connections.size,
        processing: STATE.processing.size,
        shuttingDown: STATE.shuttingDown
      };
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(status));
    } else {
      res.writeHead(404);
      res.end('Not found');
    }
  } catch (err) {
    if (!res.headersSent) {
      res.writeHead(500);
      res.end('Processing error');
    }
  } finally {
    STATE.activeRequests--;
  }
});

server.listen(3000, () => console.log('Image processor listening on :3000'));

module.exports = { server, STATE, processImage, pool };
